import { describe, it, expect } from 'vitest';
import { jsPDF } from 'jspdf';
import { embedImages } from '@/lib/export';

// A real 240×140 JPEG (inlined so the test is self-contained in CI).
const JPEG = 'data:image/jpeg;base64,';

describe('embedImages — screenshots really land in the PDF', () => {
  it('reads the image size, adds a page, and embeds a JPEG stream', () => {
    const doc = new jsPDF();
    const pagesBefore = doc.getNumberOfPages();

    // jsPDF parses the dimensions from the bytes — proves the image is decodable.
    const props = doc.getImageProperties(JPEG);
    expect(props.width).toBe(240);
    expect(props.height).toBe(140);

    embedImages(doc as never, [{ caption: 'Sign in — blank screen', dataUrl: JPEG }]);
    expect(doc.getNumberOfPages()).toBe(pagesBefore + 1); // one page per screenshot

    const pdf = Buffer.from(doc.output('arraybuffer') as ArrayBuffer).toString('latin1');
    expect(pdf).toContain('/DCTDecode'); // a JPEG image XObject is present in the file
    expect(pdf).toContain('/Image');
  });

  it('skips a non-image gracefully (no extra page, no throw)', () => {
    const doc = new jsPDF();
    const before = doc.getNumberOfPages();
    embedImages(doc as never, [{ dataUrl: 'not-an-image' }]);
    expect(doc.getNumberOfPages()).toBe(before);
  });
});
